import { errorResult, type CliCommandResult } from '../envelope';
import { LibraryError } from '../../services/libraryErrors';
import { ProjectLibrary } from '../../services/ProjectLibrary';
import { VariantHistoryService } from '../../services/VariantHistoryService';
import { parseDirectionAddress } from '../../services/directionRefs';
import { resolveProjectDirection } from '../../services/projectDirections';
import { errorMessage } from '../../utils/errorMessage';
import type {
  DirectionRef,
  DirectionResolution,
  DirectionSearchAddress,
} from '../../types/direction-ref';

export type DirectionTarget = {
  projectId?: string;
  sessionId: string;
  variantId: string;
  directionRef?: DirectionRef;
};

type DirectionTargetResult =
  | { ok: true; target: DirectionTarget }
  | { ok: false; result: CliCommandResult };

const resolveInProject = async (args: {
  projectPath: string;
  address: DirectionSearchAddress;
}): Promise<{ projectId?: string; resolution: DirectionResolution }> => {
  const library = ProjectLibrary.openReadOnly();
  try {
    const owner = library?.registry.findByPath(args.projectPath);
    if (library && owner)
      return {
        projectId: owner.id,
        resolution: await resolveProjectDirection({
          source: { kind: 'library', library, projectId: owner.id },
          address: args.address,
        }),
      };
    const history = new VariantHistoryService();
    try {
      return {
        resolution: await resolveProjectDirection({
          source: { kind: 'history', history, projectPath: args.projectPath },
          address: args.address,
        }),
      };
    } finally {
      history.metadata.closeAll();
    }
  } finally {
    library?.close();
  }
};

export const resolveDirectionTarget = async (args: {
  command: string;
  projectPath: string;
  input: string;
  usage: string;
}): Promise<DirectionTargetResult> => {
  const address = parseDirectionAddress(args.input);
  if (!address)
    return {
      ok: false,
      result: errorResult(args.command, 'USAGE_ERROR', args.usage),
    };
  if (address.kind === 'ids') {
    const { projectId, sessionId, variantId } = address;
    return {
      ok: true,
      target: { ...(projectId ? { projectId } : {}), sessionId, variantId },
    };
  }
  try {
    const { projectId, resolution } = await resolveInProject({
      projectPath: args.projectPath,
      address,
    });
    if (!resolution.isResolved)
      return {
        ok: false,
        result: errorResult(args.command, resolution.code, resolution.message, {
          input: args.input.trim(),
          candidates: resolution.candidates,
        }),
      };
    const { directionRef, sessionId, variantId } = resolution.direction;
    return {
      ok: true,
      target: {
        ...(projectId ? { projectId } : {}),
        sessionId,
        variantId,
        directionRef,
      },
    };
  } catch (error) {
    const isMissingProject =
      error instanceof LibraryError && error.code === 'project_not_found';
    return {
      ok: false,
      result: errorResult(
        args.command,
        isMissingProject ? 'WORK_ITEM_NOT_FOUND' : 'OPERATION_FAILED',
        errorMessage(error),
      ),
    };
  }
};
